    17	impl<'a, 'c> Reader<'a, 'c> {
    18	    pub fn new(source: &'a [u8], cancel: Option<&'c mut dyn FnMut() -> bool>) -> Self {
    19	        Self { source, cursor: 0, cancel, canceled: false }
    20	    }
    21	    pub fn failure(&self, error: Error, offset: usize) -> DecodeFailure {
    22	        DecodeFailure { error, offset, canceled: self.canceled }
    23	    }
    24	    pub fn poll(&mut self) -> Result<(), DecodeFailure> {
    25	        if self.cursor != 0 && self.cursor & 4095 == 0 {
    26	            if self.cancel.as_mut().is_some_and(|check| check()) {
    27	                self.canceled = true;
    28	                return Err(self.failure(Error::InvalidArgument, self.cursor));
    29	            }
    30	        }
    31	        Ok(())
    32	    }
    33	    pub fn space(&mut self) -> Result<(), DecodeFailure> {
    34	        loop {
    35	            self.poll()?;
    36	            match self.source.get(self.cursor) {
    37	                Some(b' ' | b'\t' | b'\r' | b'\n') => self.cursor += 1,
    38	                _ => return Ok(()),
    39	            }
    40	        }
    41	    }
    42	    pub fn scan(&mut self, depth: usize) -> Result<(), DecodeFailure> {
    43	        self.space()?;
    44	        if depth > MAX_DEPTH { return Err(self.failure(Error::Limit, self.cursor)); }
    45	        let byte = *self.source.get(self.cursor).ok_or_else(|| self.failure(Error::MalformedJson, self.cursor))?;
   210	    Some(out)
   211	}
