   257	pub(crate) fn object_fields(source: &[u8], span: Span, cancel: Option<&mut dyn FnMut() -> bool>) -> Result<Vec<Field>, DecodeFailure> {
   258	    let mut reader = Reader::new(source, cancel); reader.cursor = span.start; reader.space()?;
   259	    if reader.source.get(reader.cursor) != Some(&b'{') { return Err(reader.failure(Error::InvalidSchema, span.start)); }
   260	    reader.cursor += 1; reader.space()?; let mut fields = Vec::new();
   261	    if reader.source.get(reader.cursor) == Some(&b'}') {
   262	        reader.cursor += 1;
   263	        if reader.cursor != span.end { return Err(reader.failure(Error::MalformedJson, reader.cursor)); }
   264	        return Ok(fields);
   265	    }
   265	    }
   266	    loop {
   267	        let key_offset = reader.cursor; let key = reader.string()?;
   268	        if fields.iter().any(|field: &Field| field.key == key) { return Err(reader.failure(Error::Duplicate, key_offset)); }
   269	        reader.space()?; if reader.source.get(reader.cursor) != Some(&b':') { return Err(reader.failure(Error::MalformedJson, reader.cursor)); }
   270	        reader.cursor += 1; reader.space()?; let start = reader.cursor;
   271	        if fields.len() == MAX_FIELDS { return Err(reader.failure(Error::Limit, start)); }
   272	        reader.scan(1)?; let end = reader.cursor;
   273	        fields.try_reserve(1).map_err(|_| reader.failure(Error::Limit, start))?;
   274	        fields.push(Field { key, value: Span { start, end } });
   275	        reader.space()?;
   276	        match reader.source.get(reader.cursor) { Some(b'}') => { reader.cursor += 1; break; }, Some(b',') => { reader.cursor += 1; reader.space()?; }, _ => return Err(reader.failure(Error::MalformedJson, reader.cursor)) }
   277	    }
   278	    if reader.cursor != span.end { return Err(reader.failure(Error::MalformedJson, reader.cursor)); }
   279	    Ok(fields)
   280	}
