   282	pub(crate) fn array_spans(source: &[u8], span: Span, limit: usize, cancel: Option<&mut dyn FnMut() -> bool>) -> Result<Vec<Span>, DecodeFailure> {
   283	    let mut reader = Reader::new(source, cancel); reader.cursor = span.start; reader.space()?;
   284	    if reader.source.get(reader.cursor) != Some(&b'[') { return Err(reader.failure(Error::InvalidSchema, span.start)); }
   285	    reader.cursor += 1; reader.space()?; let mut spans = Vec::new();
   286	    if reader.source.get(reader.cursor) == Some(&b']') { reader.cursor += 1; }
   287	    else { loop {
   288	        if spans.len() == limit { return Err(reader.failure(Error::Limit, reader.cursor)); }
   289	        let start = reader.cursor; reader.scan(1)?; spans.try_reserve(1).map_err(|_| reader.failure(Error::Limit, start))?;
   290	        spans.push(Span { start, end: reader.cursor }); reader.space()?;
   291	        match reader.source.get(reader.cursor) { Some(b']') => { reader.cursor += 1; break; }, Some(b',') => { reader.cursor += 1; reader.space()?; }, _ => return Err(reader.failure(Error::MalformedJson, reader.cursor)) }
   292	    } }
   293	    if reader.cursor != span.end { return Err(reader.failure(Error::MalformedJson, reader.cursor)); }
   294	    Ok(spans)
   295	}
    55	pub fn decode<'a>(source: &'a [u8], context: &TimelineContext) -> Result<TimelineView<'a>> {
    56	    decode_cancellable(source, context, None::<fn() -> bool>)
    57	}
    58	pub fn decode_cancellable<'a, F>(source: &'a [u8], context: &TimelineContext, cancel: Option<F>) -> Result<TimelineView<'a>>
    59	where F: FnMut() -> bool {
    60	    validate_context(context)?;
    61	    if source.is_empty() { return Ok(TimelineView { source, tracks: Vec::new(), tracks_span: Span {start:0,end:0},
    62	        ticks_per_second:0,duration_ticks:0,fps_numerator:0,fps_denominator:0,loop_mode:LoopMode::Once,
    63	        onion_before:0,onion_after:0,onion_opacity:0.0,empty:true }); }
    64	    if source.len() > MAX_SOURCE_BYTES { return Err(DecodeFailure { error:Error::Limit,offset:0,canceled:false }); }
    65	    let mut callback = cancel;
    66	    let mut poll_cancel = || callback.as_mut().is_some_and(|check| check());
    67	    let mut reader = Reader::new(source, Some(&mut poll_cancel));
    68	    reader.scan(0)?;
    69	    let root_end = reader.cursor; reader.space()?;
    70	    if reader.cursor != source.len() { return Err(reader.failure(Error::MalformedJson, reader.cursor)); }
    71	    drop(reader);
    72	    let root = object_fields(source, Span {start:0,end:root_end},Some(&mut poll_cancel))?;
    73	    let schema = required(&root,b"schema").ok_or(DecodeFailure{error:Error::UnsupportedVersion,offset:0,canceled:false})?;
    74	    let schema_value = string(source,schema.value).map_err(|_| DecodeFailure{error:Error::InvalidSchema,offset:schema.value.start,canceled:false})?;
    75	    if schema_value != b"vexel.animation" { return Err(DecodeFailure{error:Error::UnsupportedVersion,offset:schema.value.start,canceled:false}); }
    76	    let version_field = required(&root,b"version").ok_or(DecodeFailure{error:Error::InvalidSchema,offset:schema.value.start,canceled:false})?;
    77	    let version = uint(source,version_field.value)?;
    78	    if version != 1 { return Err(DecodeFailure{error:Error::UnsupportedVersion,offset:version_field.value.start,canceled:false}); }
    79	    require_fields(&root,&[b"schema",b"version",b"ticks_per_second",b"duration_ticks",b"fps",b"loop",b"onion",b"tracks"],0)?;
    80	    let tps_span = required(&root,b"ticks_per_second").ok_or_else(|| at(Error::InvalidSchema,0))?.value;
    81	    let duration_span = required(&root,b"duration_ticks").ok_or_else(|| at(Error::InvalidSchema,0))?.value;
    82	    let tps=uint(source,tps_span)?; let duration=uint(source,duration_span)?;
    83	    if tps==0 || tps>240 { return Err(at(Error::InvalidValue,tps_span.start)); }
    84	    if duration==0 || duration>14_400_000 { return Err(at(Error::InvalidValue,duration_span.start)); }
    85	    let fps_span=required(&root,b"fps").ok_or_else(|| at(Error::InvalidSchema,0))?.value;
    86	    let fps=object_fields(source,fps_span,Some(&mut poll_cancel))?; require_fields(&fps,&[b"numerator",b"denominator"],fps_span.start).map_err(|_| at(Error::InvalidValue,fps_span.start))?;
    87	    let num_field=required(&fps,b"numerator").ok_or_else(||at(Error::InvalidValue,fps_span.start))?;
    88	    let den_field=required(&fps,b"denominator").ok_or_else(||at(Error::InvalidValue,fps_span.start))?;
    89	    let numerator=uint(source,num_field.value)?; let denominator=uint(source,den_field.value)?;
    90	    if numerator==0 || denominator==0 || (u64::from(tps)*u64::from(denominator))%u64::from(numerator)!=0 { return Err(at(Error::InvalidValue,fps_span.start)); }
    91	    let loop_span=required(&root,b"loop").ok_or_else(||at(Error::InvalidSchema,0))?.value;
    92	    let loop_text=string(source,loop_span).map_err(|_|at(Error::InvalidValue,loop_span.start))?;
    93	    let loop_mode=match loop_text.as_slice(){b"once"=>LoopMode::Once,b"loop"=>LoopMode::Repeat,b"ping_pong"=>LoopMode::PingPong,_=>return Err(at(Error::InvalidValue,loop_span.start))};
    94	    let onion_span=required(&root,b"onion").ok_or_else(||at(Error::InvalidSchema,0))?.value;
    95	    let onion=object_fields(source,onion_span,Some(&mut poll_cancel))?; require_fields(&onion,&[b"before",b"after",b"opacity"],onion_span.start).map_err(|_|at(Error::InvalidValue,onion_span.start))?;
    96	    let before_span=required(&onion,b"before").ok_or_else(||at(Error::InvalidValue,onion_span.start))?.value;
    97	    let after_span=required(&onion,b"after").ok_or_else(||at(Error::InvalidValue,onion_span.start))?.value;
    98	    let opacity_span=required(&onion,b"opacity").ok_or_else(||at(Error::InvalidValue,onion_span.start))?.value;
    99	    let before=uint(source,before_span).map_err(|_|at(Error::InvalidValue,onion_span.start))?;
   100	    let after=uint(source,after_span).map_err(|_|at(Error::InvalidValue,onion_span.start))?;
   101	    let opacity=number(source,opacity_span).map_err(|_|at(Error::InvalidValue,opacity_span.start))?;
   102	    if before>8 || after>8 || !(0.0..=1.0).contains(&opacity) { return Err(at(Error::InvalidValue,opacity_span.start)); }
   103	    let tracks_field=required(&root,b"tracks").ok_or_else(||at(Error::InvalidSchema,0))?;
   104	    let track_spans=array_spans(source,tracks_field.value,MAX_TRACKS,Some(&mut poll_cancel))?;
   105	    let mut metas=Vec::new(); metas.try_reserve_exact(track_spans.len()).map_err(|_|at(Error::Limit,tracks_field.value.start))?;
   106	    let mut ids: Vec<Vec<u8>>=Vec::new(); let mut total_items=0usize;
   107	    for span in &track_spans {
   108	        let fields=object_fields(source,*span,Some(&mut poll_cancel))?;
   109	        let kind_field=required(&fields,b"kind").ok_or_else(||at(Error::InvalidSchema,span.start))?;
   110	        let kind=string(source,kind_field.value).map_err(|_|at(Error::InvalidSchema,span.start))?;
   111	        let drawing=kind==b"drawing";
   112	        if !drawing && kind!=b"property" { return Err(at(Error::InvalidValue,kind_field.value.start)); }
   113	        let id_field=required(&fields,b"id").ok_or_else(||at(Error::InvalidSchema,span.start))?;
   114	        let target_field=required(&fields,b"target").ok_or_else(||at(Error::InvalidSchema,span.start))?;
   115	        let visible_field=required(&fields,b"visible").ok_or_else(||at(Error::InvalidSchema,span.start))?;
   116	        let id=string(source,id_field.value).map_err(|_|at(Error::InvalidSchema,span.start))?;
   117	        let target=string(source,target_field.value).map_err(|_|at(Error::InvalidSchema,span.start))?;
   118	        let visible=boolean(source,visible_field.value).map_err(|_|at(Error::InvalidSchema,span.start))?;
   119	        let _ = visible;
   120	        if !valid_track_id(&id) || target.is_empty() || target.len()>256 { return Err(at(Error::InvalidSchema,span.start)); }
   121	        if ids.iter().any(|prior|prior==&id) { return Err(at(Error::Duplicate,id_field.value.start)); }
   122	        if ids.len()==MAX_TRACKS { return Err(at(Error::Limit,span.start)); }
   123	        ids.try_reserve(1).map_err(|_|at(Error::Limit,span.start))?; ids.push(id);
   124	        if context.scene_ids.binary_search(&target).is_err() { return Err(at(Error::InvalidReference,target_field.value.start)); }
   125	        let name=field(&fields,b"name"); if let Some(n)=name { string(source,n.value)?; }
   126	        let items_field=required(&fields,if drawing {b"cels"} else {b"keys"}).ok_or_else(||at(Error::InvalidSchema,span.start))?;
   127	        if drawing {
   128	            require_track_fields(&fields,name.is_some(),true,*span)?;
   129	        } else {
   130	            require_track_fields(&fields,name.is_some(),false,*span)?;
   131	            validate_property(source,&fields,*span)?;
   132	        }
   133	        let item_spans=array_spans(source,items_field.value,MAX_ITEMS_PER_TRACK,Some(&mut poll_cancel))?;
   134	        if item_spans.is_empty() { return Err(at(Error::InvalidValue,items_field.value.start)); }
   135	        let type_val=field(&fields,b"value_type").map(|f|string(source,f.value)).transpose()?.unwrap_or_default();
   136	        let mut previous=0u32;
   137	        for (index,item_span) in item_spans.iter().enumerate() {
   138	            let item_fields=object_fields(source,*item_span,Some(&mut poll_cancel))?;
   139	            if drawing {
   140	                validate_item_fields(&item_fields,&[b"tick",b"asset",b"label"],&[b"tick",b"asset"],*item_span)?;
   141	            } else {
   142	                require_fields(&item_fields,&[b"tick",b"value"],item_span.start)?;
   143	            }
   144	            let tick_field=required(&item_fields,b"tick").ok_or_else(||at(Error::InvalidSchema,item_span.start))?;
   145	            let tick=uint(source,tick_field.value)?;
   146	            if tick>=duration { return Err(at(Error::InvalidValue,tick_field.value.start)); }
   147	            if drawing {
   148	                let asset_field=required(&item_fields,b"asset").ok_or_else(||at(Error::InvalidSchema,item_span.start))?;
   149	                let asset_name=string(source,asset_field.value)?;
   150	                if let Some(label)=field(&item_fields,b"label") { string(source,label.value)?; }
   151	                if (index==0 && tick!=0)||(index>0&&tick<=previous) { return Err(at(Error::Duplicate,item_span.start)); }
   152	                previous=tick;
   153	                if !context.assets.iter().any(|a|a.name==asset_name&&a.media_type==b"image/svg+xml") { return Err(at(Error::InvalidReference,item_span.start)); }
   154	            } else {
   155	                let value=required(&item_fields,b"value").ok_or_else(||at(Error::InvalidSchema,item_span.start))?.value;
   156	                validate_typed_value(source,value,&type_val,&mut poll_cancel)?;
   157	                if (index==0 && tick!=0)||(index>0&&tick<=previous) { return Err(at(Error::Duplicate,item_span.start)); }
   158	                previous=tick;
   159	            }
   160	        }
   161	        total_items=total_items.checked_add(item_spans.len()).ok_or_else(||at(Error::Limit,items_field.value.start))?;
   162	        if total_items>MAX_ITEMS { return Err(at(Error::Limit,items_field.value.start)); }
   163	        metas.push(TrackMeta {span:*span,items:items_field.value,drawing,item_count:item_spans.len()});
   164	    }
   165	    Ok(TimelineView {source,tracks:metas,tracks_span:tracks_field.value,ticks_per_second:tps,duration_ticks:duration,
   166	        fps_numerator:numerator,fps_denominator:denominator,loop_mode,onion_before:before,onion_after:after,onion_opacity:opacity,empty:false})
   167	}
