   169	pub fn classify(source:&[u8]) -> Result<bool> { classify_cancellable(source,None::<fn()->bool>) }
   170	pub fn classify_cancellable<F>(source:&[u8],cancel:Option<F>) -> Result<bool>
   171	where F:FnMut()->bool {
   172	    if source.len()>MAX_SOURCE_BYTES { return Err(at(Error::Limit,0)); }
   173	    let mut callback=cancel;
   174	    let mut poll_cancel=||callback.as_mut().is_some_and(|f|f());
   175	    let mut reader=Reader::new(source,Some(&mut poll_cancel)); reader.scan(0)?; let end=reader.cursor; reader.space()?;
   176	    if reader.cursor!=source.len() { return Err(reader.failure(Error::MalformedJson,reader.cursor)); }
   177	    drop(reader);
   178	    let root=object_fields(source,Span{start:0,end},Some(&mut poll_cancel))?;
   179	    let Some(s)=field(&root,b"schema") else{return Ok(false)};
   180	    let value=string(source,s.value)?; if value!=b"vexel.animation" {return Ok(false)}
    40	    assert_eq!(view.item_next(0,&mut it).unwrap().tick,0);
    41	    assert_eq!(view.item_next(1,&mut it),None);
    42	    it=TimelineIterator::default(); assert_eq!(view.item_next(1,&mut it).unwrap().value_json,Some(&b"0"[..]));
    43	}
