    45	#[test]
    46	fn escaped_keys_surrogates_and_duplicate_decoded_fields() {
    47	    let escaped=base(r#"[{"id":"wa\u006bk","kind":"draw\u0069ng","target":"lay\u0065r1","visible":true,"cels":[{"tick":0,"asset":"ce\u006c0"}]}]"#);
    48	    let view=decode(escaped.as_bytes(),&context()).unwrap(); assert_eq!(view.track_at(0).unwrap().id,b"wa\\u006bk");
    49	    assert!(classify(escaped.as_bytes()).unwrap()); assert!(!classify(b"{\"schema\":\"future\",\"version\":1}").unwrap());
    50	    let dup=base(r#"[]"#).replace("\"numerator\":24", "\"numerator\":24,\"num\\u0065rator\":24");
    51	    let duplicate=decode(dup.as_bytes(),&context()).unwrap_err();
    52	    assert_eq!(duplicate.error,Error::Duplicate);
    53	    assert_eq!(duplicate.offset,dup.find("\"num\\u0065rator\"").unwrap());
    54	    let malformed_surrogate=br#""\uD800\u0041""#;
    55	    let surrogate=decode(malformed_surrogate,&context()).unwrap_err();
    56	    assert_eq!(surrogate.error,Error::MalformedJson);
    57	    assert_eq!(surrogate.offset,malformed_surrogate.len()-1);
    58	    assert_eq!(decode(br#""\uD83D\uDE00""#,&context()).unwrap_err().error,Error::InvalidSchema);
    59	    let mut output=[0u8;8]; let count=string_copy(br#"a\u0062\uD83D\uDE00"#,&mut output).unwrap();
    60	    assert_eq!(&output[..count],"ab😀".as_bytes());
    61	    assert_eq!(string_copy(b"\\u0061",&mut [0u8;0]),None);
    62	    assert_eq!(string_copy(br#"\uD800"#,&mut output),None);
    63	    let oversized_schema=format!("{{\"schema\":\"{}\"}}","x".repeat(4097));
    64	    assert_eq!(decode(oversized_schema.as_bytes(),&context()).unwrap_err().error,Error::Limit);
    65	}
