    68	fn string_copy_enforces_decoded_byte_limit_with_large_output() {
    69	    let valid=vec![b'a';4096]; let too_long=vec![b'a';4097];
    70	    let mut valid_output=vec![0;8192]; let mut long_output=vec![0;8192];
    71	    assert_eq!(string_copy(&valid,&mut valid_output),Some(4096));
