    76	fn exact_error_categories_and_offsets() {
    77	    let json=base("[]").replace("\"ticks_per_second\":24","\"ticks_per_second\":0");
    78	    let result=decode(json.as_bytes(),&context()).unwrap_err();
    79	    assert_eq!(result.error,Error::InvalidValue);
    80	    assert_eq!(result.offset,json.find("\"ticks_per_second\":0").unwrap()+"\"ticks_per_second\":".len());
    81	    assert_eq!(decode(b"{\"schema\":",&context()).unwrap_err().error,Error::MalformedJson);
    82	    assert_eq!(decode(b"{\"schema\":\"future.timeline\",\"version\":2}",&context()).unwrap_err().error,Error::UnsupportedVersion);
    83	    assert_eq!(decode(b"{}",&context()).unwrap_err().error,Error::UnsupportedVersion);
